import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a DRAFT or OPEN claim can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
};

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to; null when its due is live. */
export function fixedDue(c: Claim): string | null {
  return c.due ?? (c.stated ? c.statedDue : null);
}

/** Whether a claim counts toward claimed and every live total, given the ids of the people on hold:
 *  only OPEN and SETTLED claims do, and a held person's OPEN claims do not. */
export function counts(c: Claim, held: ReadonlySet<number>): boolean {
  return c.status === 'SETTLED' || (c.status === 'OPEN' && !held.has(c.personId));
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
  });
}

/** The sum of the amounts of those of these claims that count (given the ids of the people on hold),
 *  with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], held: ReadonlySet<number>): string {
  const cents = claims.filter((c) => counts(c, held)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, heldIds, usePeople } from '../people/usePeople';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (a held
 *  person's OPEN claims left out; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const floor = settings?.floor;
  const held = heldIds(people.data);
  const totals = new Map<number, string>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, held));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), floor, settings, today.data?.today));
    totals.set(p.id, rated || counting.some((c) => fixedDue(c) !== null) || dues.some((d) => d !== 'n/a')
      ? sumDues(dues)
      : 'n/a');
  }
  return totals;
}
import { counts, fixedDue, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, heldIds, usePeople } from '../people/usePeople';
import { due, isCorrection, rateFor, sumDues, useRates, withCharge } from '../rates/useRates';
import { useSettings, type Settings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** A claim's due-by: its date (yyyy-mm-dd) plus the sheet's terms in days. */
export function dueBy(date: string, terms: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function isOverdue(c: Claim, terms: number, today: string): boolean {
  return c.status === 'OPEN' && dueBy(c.date, terms) < today;
}

/** Whether a claim's live figures (its rate step and late charge) round half up: when the claim is
 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
  if (policy === undefined) return false;
  const corrected = c.corrects === null
    ? undefined
    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
  return (corrected?.date ?? c.date) < policy;
}

/** A claim's due now: its figure (a settled claim's frozen due, else the one its last statement
 *  bound it to, else its floored live due), plus, while it is overdue, the sheet's late percent of
 *  that figure for every full 30 days it is overdue, rounded like a due. The charge is never bound by
 *  a statement: it follows the sheet's today until settling freezes it in. A correction (a negative
 *  amount) has no late charge. Just the figure until the settings and the sheet's today are loaded. */
export function dueNow(c: Claim, figure: string, settings: Settings | undefined, today: string | undefined, halfUp: boolean): string {
  if (settings === undefined || today === undefined || !isOverdue(c, settings.terms, today) || isCorrection(c.amount)) {
    return figure;
  }
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(c.date, settings.terms)}T00:00:00Z`)) / 86_400_000;
  return withCharge(figure, settings.latePct, Math.floor(days / 30), halfUp);
}

/** A claim's due now (see `dueNow`) from its fixed figure, else its live due at this rate (a
 *  two-decimal percent; undefined when none applies) and floor, every rounding by the claim's policy
 *  (see `roundsHalfUp`) — the other claims on the sheet are what a correction is looked up in. */
export function claimDueNow(c: Claim, claims: Claim[] | undefined, pct: string | undefined, floor: string | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  const up = roundsHalfUp(c, claims, settings, today);
  return dueNow(c, fixedDue(c) ?? due(c.amount, pct, floor, up), settings, today, up);
}

/** Each person's overdue figures, by person id: how many of their claims that count are overdue, and
 *  the sum of those claims' dues now (a stated claim's bound figure, else its live due, with its late
 *  charge), skipping
 *  those with none. Empty until the terms and the sheet's today are loaded. */
export function useOverdue(sheetId: string): Map<number, { count: number; total: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const held = heldIds(people.data);
  const figures = new Map<number, { count: number; total: string }>();
  if (settings === undefined || today === undefined) return figures;
  for (const p of people.data ?? []) {
    const overdue = (claims.data ?? []).filter(
      (c) => c.personId === p.id && counts(c, held) && isOverdue(c, settings.terms, today),
    );
    figures.set(p.id, {
      count: overdue.length,
      total: sumDues(overdue.map((c) =>
        claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings.floor, settings, today))),
    });
  }
  return figures;
}
